"""Source-reviewed orientation and contracts for algorithm families."""


def section(title, *paragraphs, columns=None, rows=None, bullets=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if columns is not None:
        result["table"] = {"columns": columns, "rows": rows}
    if bullets is not None:
        result["bullets"] = bullets
    return result


def entry(name, header, summary, *sections):
    return {"name": name, "header": header, "summary": summary, "sections": list(sections)}


